{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE cp_2 as( select * from ( SELECT *, CASE WHEN DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE) > MAX_SLA THEN \'breach\' ELSE \'non-breach\' END AS breach_flag, (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) AS breach_date, CASE WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) < -2 THEN \'-3\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = -2 THEN \'-2\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = -1 THEN \'-1\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 0 THEN \'0\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 1 THEN \'1\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 2 THEN \'2\' ELSE \'3\' END AS breach_date_category, (DATEDIFF(\'hour\', OUTFORDELIVERY_DATE, MAX_SLA) * -1) AS breach_hours, DATEDIFF(\'hour\', PICKUP_DATE, OUTFORDELIVERY_DATE) AS actual_sla_shipping_hrs, DATEDIFF(\'day\', PICKUP_DATE, OUTFORDELIVERY_DATE) AS actual_sla_shipping_days, DATEDIFF(\'hour\', ORDER_DATE, OUTFORDELIVERY_DATE) AS actual_sla_delivery_hrs, DATEDIFF(\'day\', ORDER_DATE,OUTFORDELIVERY_DATE ) AS actual_sla_delivery_days, DATEDIFF(\'day\',PICKUP_DATE,MAX_SLA) AS predicted_tat FROM cp_1 where order_date > \'2024-07-01\' AND status = \'DELIVERED\' AND JOURNEY= \'Forward\' )A left join ( select * from ( SELECT ZONE AS Zone_m, City_Tier AS City_Tier, Delivery_Postcode, ROW_NUMBER() OVER (PARTITION BY Delivery_Postcode ORDER BY 1) AS rn FROM snitch_db.maplemonk.pincodemappingzoneupdatedsnitch ) WHERE rn=1) B on A.PINCODE = B.DELIVERY_POSTCODE ); CREATE OR REPLACE TABLE cp_4 as select * from ( WITH weekly_pincode_volume AS ( SELECT PINCODE, DATE_TRUNC(\'WEEK\', OUTFORDELIVERY_DATE) AS week, COUNT(*) AS order_count, COUNT(CASE WHEN breach_flag = \'breach\' THEN 1 END) AS breach_count FROM cp_2 GROUP BY PINCODE, DATE_TRUNC(\'WEEK\', OUTFORDELIVERY_DATE) ), ranked_pincodes AS ( SELECT PINCODE, week, order_count, SUM(order_count) OVER (PARTITION BY week ORDER BY order_count DESC) AS cumulative_volume, SUM(order_count) OVER (PARTITION BY week) AS total_weekly_volume, breach_count, (breach_count::FLOAT / order_count) * 100 AS breach_percentage FROM weekly_pincode_volume ), pincode_percentage AS ( SELECT PINCODE, week, order_count, cumulative_volume, total_weekly_volume,breach_percentage, cumulative_volume / total_weekly_volume AS cumulative_percentage FROM ranked_pincodes ) SELECT PINCODE, week, order_count, cumulative_percentage,breach_percentage, CASE WHEN cumulative_percentage <= 0.50 THEN \'top50%\' WHEN cumulative_percentage > 0.50 AND cumulative_percentage <= 0.80 THEN \'top80%\' WHEN cumulative_percentage > 0.80 AND cumulative_percentage <= 0.90 THEN \'top85-90%\' ELSE \'top90-100%\' END AS pincode_category FROM pincode_percentage ORDER BY week, cumulative_percentage ) where week is not null",
                    "transaction": true
                }
            ) }}
